function _RecurseAddProp(prop, depth, _firstElement, _countOfElements)
{
    if(depth++ > 16 || prop == null || typeof prop == "function")
    {
        return;
    }
    if(typeof prop._attributes == "undefined")
    {
        prop._attributes = {};
    }

    if(typeof prop._attributes == "object")
    {
        if(typeof prop._attributes._firstElement == "undefined")
        {
            prop._attributes._firstElement = _firstElement;
        }
        if(typeof prop._attributes._countOfElements == "undefined")
        {
            prop._attributes._countOfElements = _countOfElements;
        }
    }
    for(child in prop)
    {
        if(child == "_attributes" || child == "_value")
        {
            continue;
        }
        _RecurseAddProp(prop[child], depth, _firstElement, _countOfElements);
    }
    return;
}

function _ShouldNotSerialize(parentObject, propName)
{
    return((typeof parentObject[propName] == "function") || !parentObject.propertyIsEnumerable(propName));
}
